import { useState } from "react";
import Calculation from "../Calculation/Calculation";

import "./Appear.css";

function Appear() {
  let buttonArr = ["Calculation", "Data"];
  const [appear, setAppear] = useState(false);

  function showHide() {
    setAppear(!appear);
    whichAppear(!appear);
  }



  return (
    <div className="mainAppear">
      <div className="buttons">
        {buttonArr.map((elm) => (
          <button key={elm} className="forAppear" onClick={showHide}>
            {elm}
          </button>
        ))}
        {appear ? <Calculation /> : <p>A</p>}
      </div>
    </div>
  );
}

export default Appear;
